#include <bits/stdc++.h>
using namespace std;

struct Val {
    long double fi, se;
    Val(double a=0.0, double b=0.0): fi(a), se(b) {}
};

Val merge(const Val& a, const Val& b) {
    return Val(a.fi + b.fi, a.se + b.se);
}

Val diff(const Val& a, const Val& b) {
    return Val(a.fi - b.fi, a.se - b.se);
}

Val scale(const Val& a, long double w) {
    return Val(a.fi * w, a.se * w);
}

Val quotient(const Val& a, long double w) {
    return Val(a.fi / w, a.se / w);
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> probs(n);
    for (int i=0; i<n; ++i) cin >> probs[i];

    for (int v=0; v<n; ++v) {
        vector<Val> dp(1<<n, Val(0.0, 0.0));
        for (int mask=0; mask<(1<<n); ++mask) {
            if (mask==0) {
                dp[mask]=Val(1.0, 0.0);
            }
        }
        for (int mask=1; mask<(1<<n); ++mask) {
            if (mask & (1<<v)) continue;
            Val sum(0.0, 0.0);
            double same=0.0;
            for (int j=0; j<n; ++j) {
                if (j!=v && (mask & (1<<j))) {
                    same+=probs[j];
                    sum= merge(sum, scale(dp[mask^(1<<j)], probs[j]));
                }
            }
            dp[mask]= quotient(sum, 1.0 - same);
        }
        Val total(1.0, 0.0);
        for (int mask=1; mask<(1<<n); ++mask) {
            if (!(mask & (1<<v))) {
                total= merge(total, dp[mask]);
            }
        }
        double alpha= (1.0 - total.se)/total.fi;
        Val bad(0.0, 0.0);
        for (int mask=0; mask<(1<<n); ++mask) {
            if (mask & (1<<v)) continue;
            if (__builtin_popcount(mask)>=k) {
                bad= merge(bad, dp[mask]);
            }
        }
        cout << fixed << setprecision(12) << 1.0 - (alpha*bad.fi + bad.se) << (v+1==n ? '\n' : ' ');
    }
    return 0;
}
